/**
 * Germany rate book (Oct 2026, docs/rates/germany-rate-book-2026-10.md): Germany's own rates — IG Metall ERA pay loaded with
 * the 2026 employer contributions for two 8-hour shifts, European market anchors in EUR, the 2 × 8 h operating model (three
 * shifts for continuous lines), Haas EU capex for CNC and a sourced extrusion line — in place of "UK × a factor". Generated by
 * scripts/country-book.ts from scripts/rate-refresh/2026-10-germany.json.
 */
import { describe, it, expect } from 'vitest';
import { DEFAULT_RATE_LIBRARY, recomputeMachineRates } from '../src/engine/rate-library.js';
import { REGIONAL_DATA, buildRegionalLibrary } from '../src/engine/regional-rates.js';
import { GERMANY_BOOK } from '../src/engine/country-books/de.js';
import { COUNTRY_BOOKS, CONTINUOUS_UK_HOURS } from '../src/engine/country-books.js';
import { BILLET_PREMIUM_USD_PER_T } from '../src/engine/al-extrusion-data.js';

const UK = recomputeMachineRates(DEFAULT_RATE_LIBRARY);
const DE = buildRegionalLibrary(UK, 'DE');
const FX = REGIONAL_DATA.DE.fxToGBP;
const eur = (gbp: number) => Math.round(gbp * FX * 100) / 100;
const mat = (id: string) => DE.materials.find(m => m.id === id)!;
const mach = (id: string) => DE.machines.find(m => m.id === id)!;
const lab = (id: string) => DE.labour.find(l => l.id === id)!;

describe('labour: IG Metall ERA pay, 2026 employer contributions, 2 × 8 h', () => {
  it('a skilled machinist is €52.45/h fully loaded (was €47.50 from an unresearched survey); lab-de agrees with the table', () => {
    expect(COUNTRY_BOOKS.DE).toBe(GERMANY_BOOK);
    expect(eur(lab('lab-uk-skilled').fullyLoadedRatePerHr)).toBeCloseTo(52.45, 1);
    expect(eur(lab('lab-uk-semiskilled').fullyLoadedRatePerHr)).toBeCloseTo(43.76, 1);
    expect(DEFAULT_RATE_LIBRARY.labour.find(l => l.id === 'lab-de-skilled')!.fullyLoadedRatePerHr).toBeCloseTo(REGIONAL_DATA.DE.labour.skilled, 6);
    expect(lab('lab-uk-forge').sourceNote).toMatch(/Germany book/);
  });
  it('a Gießereimechaniker is a skilled ERA grade — foundry is no longer below semi-skilled', () => {
    expect(REGIONAL_DATA.DE.labour.foundry).toBeGreaterThan(REGIONAL_DATA.DE.labour.semiskilled);
  });
  it('Austria still follows Germany by the Eurostat ratio (it is generated from the German table)', () => {
    expect(REGIONAL_DATA.AT.labour.skilled / REGIONAL_DATA.DE.labour.skilled).toBeCloseTo(44.5 / 43.4, 3);
  });
});

describe('energy', () => {
  it('electricity at the BDEW 2026 industry price €0.172/kWh (was €0.232); gas at the Destatis non-household average', () => {
    expect(eur(REGIONAL_DATA.DE.energy.electricityPerKwh)).toBeCloseTo(0.172, 2);
    expect(eur(REGIONAL_DATA.DE.energy.gasPerKwh)).toBeCloseTo(0.0629, 2);
    const e = DEFAULT_RATE_LIBRARY.energy.find(x => x.id === 'energy-de')!;
    expect(e.electricityPerKwh).toBe(REGIONAL_DATA.DE.energy.electricityPerKwh);
    expect(e.sourceNote).toMatch(/^Germany rate book/);
  });
});

describe('machines: the 2 × 8 h operating model; continuous lines on three shifts', () => {
  it('a 3-axis VMC is the Haas EU €64,995 machine over 4,044 h, machine only', () => {
    const v = mach('mach-vmc3');
    expect(v.buildup.annualAvailableHours).toBe(4044);
    expect(v.sourceNote).toMatch(/Haas VF-2SSYT-EU/);
    expect(v.confidence).toBe('Medium');
  });
  it('a continuous line (the UK book runs it ≥ 6,000 h) runs three shifts, not the plant\'s two', () => {
    const line = mach('al-ext-press-1800t'), oven = mach('al-age-oven-batch');
    expect(UK.machines.find(m => m.id === 'al-ext-press-1800t')!.buildup.annualAvailableHours).toBeGreaterThanOrEqual(CONTINUOUS_UK_HOURS);
    expect(line.buildup.annualAvailableHours).toBe(6066);
    expect(oven.buildup.annualAvailableHours).toBe(6066);
    expect(line.sourceNote).toMatch(/continuous line/);
    expect(mach('forge-press-500t').buildup.annualAvailableHours).toBe(4044);   // UK 3,500 h: a two-shift press
  });
  it('the extrusion line is the sourced ~€10 M 7-inch line, Low; a machine without capex says its capital is HELD', () => {
    expect(mach('al-ext-press-1800t').sourceNote).toMatch(/€10,000,000/);
    expect(mach('al-ext-press-1800t').confidence).toBe('Low');
    expect(mach('forge-press-1600t').sourceNote).toMatch(/capital HELD/);
    expect(mach('forge-press-1600t').confidence).toBe('Low');
  });
  it('marketplace listings are not prices: the TruBend and the SPINNER VMC stay held', () => {
    expect(mach('brake-trumpf-trubend3100').sourceNote).toMatch(/HELD/);
    expect(mach('mach-vmc3-de').sourceNote).toMatch(/HELD/);
  });
});

describe('materials: European market anchors in EUR', () => {
  it('CR sheet at the NW Europe price; HRC; the note says €', () => {
    expect(mat('mat-dc01').pricePerKg * FX).toBeCloseTo(0.865, 3);
    expect(mat('mat-dc01').sourceNote).toMatch(/Germany book .*€0\.865\/kg/);
  });
  it('a casting grade is the metal CHARGE — never below the scrap it is melted from (the UK × factor sat below it)', () => {
    const scrap = 0.275;
    for (const id of ['mat-gjl250', 'mat-gjs500', 'mat-gs-c25', 'mat-astm-a216-wcb', 'mat-g20mn5']) expect(eur(mat(id).pricePerKg), id).toBeGreaterThan(scrap);
    expect(eur(mat('mat-gjl250').pricePerKg)).toBeCloseTo(0.349, 2);
  });
  it('no grade below the metal it contains: copper, brass, bronze, primary cast aluminium', () => {
    expect(eur(mat('mat-c101-bar').pricePerKg)).toBeGreaterThanOrEqual(13.19);
    expect(eur(mat('mat-brass-cz121').pricePerKg)).toBeGreaterThanOrEqual(11.16);
    expect(eur(mat('mat-lm25').pricePerKg)).toBeGreaterThanOrEqual(3.56);
  });
  it('engineering bar has no German base price: C45 / 38MnVS6 / 6082 bar are held and say so, country first, Low', () => {
    for (const id of ['mat-steel-c45', 'mat-steel-38mnvs6', 'mat-al6082-bar']) {
      expect(mat(id).sourceNote, id).toMatch(/^Germany: no Germany price for this grade/);
      expect(mat(id).confidence, id).toBe('Low');
    }
  });
  it('every book price says what it is, where it came from and how sure it is', () => {
    for (const [id, p] of Object.entries(GERMANY_BOOK.materials)) {
      expect(p.basis.length, id).toBeGreaterThan(20);
      expect(p.source, id).toMatch(/https?:\/\//);
      expect(['High', 'Medium', 'Low']).toContain(p.confidence);
    }
  });
  it('the extrusion billet premium is the DDP North Germany print', () => {
    expect(BILLET_PREMIUM_USD_PER_T.DE.sourced).toBe(true);
    expect(BILLET_PREMIUM_USD_PER_T.DE.usdPerT).toBe(1102);
    expect(BILLET_PREMIUM_USD_PER_T.DE.basis).toMatch(/\$1,070–1,135/);
  });
});

describe('Germany live review (Oct 2026): what the reports print', () => {
  it('a continuous line states its own hours only — not the plant pattern\'s 4,044 h as well', () => {
    const note = mach('al-age-oven-batch').sourceNote ?? '';
    expect(note).toMatch(/6,066 h/);
    expect(note).not.toMatch(/4,044/);
  });
  it('a book labour rate carries the book\'s date, not the UK entry\'s', () => {
    expect(lab('lab-uk-skilled').effectiveDate).toBe(GERMANY_BOOK.asOf);
  });
  it('the overhead / packaging / logistics defaults say they are the UK basis × the country multipliers, held', async () => {
    const { shopDefaultsBasis } = await import('../src/engine/regional-rates.js');
    expect(shopDefaultsBasis('DE')).toMatch(/UK basis .* Germany's multipliers — overhead ×[\d.]+.*Held, not researched for Germany/);
    expect(shopDefaultsBasis('UK')).not.toMatch(/multipliers/);
  });
});
